def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            v_without_build = v[:v.index('+')]
        else:
            v_without_build = v

        # Split pre-release (everything after '-')
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(int(x) for x in version_part.split('.'))

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_ids = prerelease_part.split('.')
            # Convert each identifier: numeric ones to (0, int), others to (1, str)
            prerelease_tuple = tuple(
                (0, int(x)) if x.isdigit() else (1, x)
                for x in prerelease_ids
            )
        else:
            prerelease_tuple = None

        return version_nums, prerelease_tuple

    def compare_key(v):
        version_nums, prerelease_tuple = parse_version(v)
        # version_nums sorts numerically
        # If prerelease_tuple is None, it should sort after versions with pre-release
        # So we use (version_nums, (1,)) for no pre-release and (version_nums, (0, prerelease_tuple)) for pre-release
        if prerelease_tuple is None:
            return (version_nums, (1,))
        else:
            return (version_nums, (0, prerelease_tuple))

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=compare_key)

